      gear: (t, u, F) => frame(V3.add(head(F, 'teo', 0), [-0.35, -0.15, 0.3]), V3.add(head(F, 'teo', 0), [0, -0.05, 0.2]), 38, t),
      clap: (t, u, F) => frame(V3.add(F.niko.hips, [0.3, 0.55, -0.9]), V3.add(F.niko.hips, [0, 0.45, -0.3]), 42, t, 0.5),
