      letters2: (t, u, F) => frame(V3.add(head(F, 'lev', 0), [0.6, -0.2, 1.4]), head(F, 'lev', -0.15), 50, t),
      red: (t, u, F) => frame([-79, 1.3, 1.5], [-80, 1.3, -3], 54, t),
      m1: (t, u, F) => frame([F.lev.hips[0], 1.35, 2.2], V3.add(F.lev.hips, [0, 0.45, 0]), 40, t, 0.3),
