      crew.forEach((id, i) => cast.push(member(id, id === 'vladik' ? 'vladikCool' : id, dance(base(-40 - 3 + i * 1.2, -1 - (i % 2) * 1.1, 0), b * 2, i % 2 === 1), t, { sings: id === 'vladik' })));
      return { cast, vehicles: [] };
