    const burst = new Builder();
    starFan(burst, 22, 3.8, 1.5, -1.7, [0.9, 0.4, 0.75, 1], [0.5, 0.05, 0.35, 1]);
    const melon = new Builder();
    spherePatch(melon, 1.15, 1.08, 1.15, -PI, PI, -PI / 2, PI / 2, 18, 12, [0.86, 0.95, 1, 0], [3, 1.5]);
