      b.at(cx, cy + 0.017, z, (h) => h.box(0.054, t, t, col));
      b.at(cx, cy - 0.017, z, (h) => h.box(0.054, t, t, col));
      b.at(cx + 0.027, cy, z, (h) => h.box(t, 0.034, t, col));
