        points: land > 0.02 ? [{ pos: [s1[0], 0.8, s1[2]], color: [2.2 * land, 0.3 * land, 0.4 * land] }] : [{ pos: [VAULT[0], 1.6, VAULT[2]], color: [0.9, 0.7, 1.2] }]
