    const sw = S(PI * beatAt(t));
    p.spine[2] += 0.03 * e * sw;
    p.neck[2] += 0.05 * e * S(PI * beatAt(t) + 0.6);
    p.spine[0] += 0.03 * e * bo;
    p.x = root.x + P.dx * C(root.ry);
    p.z = root.z - P.dx * S(root.ry);
    p.ry = root.ry;
    p.skirtSwing = 0.05 * e * sw;
    p.hair = 0.04 * e * sw;
    p.face = faceAt(t, P);
