      const np = [C(p[2]), S(p[2]), 0], nq = [C(q[2]), S(q[2]), 0];
      b.quad([p[0], p[1], z0], [q[0], q[1], z0], [q[0], q[1], z1], [p[0], p[1], z1], side, null, [np, nq, nq, np]);
