      return view(drift([T.x + 0.05, T.y + 0.12, T.z + 0.82], [T.x + 0.02, T.y + 0.1, T.z + 0.72], u), [T.x, T.y + 0.06, T.z], 40, { light: 'tvpile', cast: [], tvs: true });
