      return view(drift([T.x - 0.1, T.y + 0.18, T.z + 0.95], [T.x - 0.05, T.y + 0.15, T.z + 0.85], u), [T.x, T.y + 0.08, T.z], 40, { light: 'tvpile', cast: [], tvs: true });
