      return view(eye, [T.x, T.y + 0.08, T.z], lerp(40, 34, k), {
        light: 'tvpile', cast: [], tvs: true,
        poster: { mode: 'front', alpha: smooth(span(t, 147.8, 149.0)) * (1 - smooth(span(t, 150.9, 152.0))) },
        swap: smooth(span(t, 151.4, 152.5))
      });
