    skirtRing(b, { n: 26, top: () => [0.14, 0.075], hem: (a, i) => [0.3 + zig(0.01)(i), -0.37 - 0.02 * backness(a)], col: (i) => (i % 2 ? WHITE : IVORY), bulge: 0.025, trim: [0.012, TEAL] });
