        h.tri([0, 0, 0.004], [S(a) * 0.024, C(a) * 0.024, 0.004], [S(a1) * 0.01, C(a1) * 0.01, 0.004], GOLD, null, [[0, 0, 1], [0, 0, 1], [0, 0, 1]]);
        h.tri([0, 0, 0.004], [S(a1) * 0.01, C(a1) * 0.01, 0.004], [S(a2) * 0.024, C(a2) * 0.024, 0.004], GOLD, null, [[0, 0, 1], [0, 0, 1], [0, 0, 1]]);
