  function energyAt(t) {
    let i = 0;
    while (i + 1 < ENERGY.length && ENERGY[i + 1][0] <= t) i++;
    const next = ENERGY[i + 1];
    if (!next) return ENERGY[i][1];
    return lerp(ENERGY[i][1], next[1], smooth(span(t, next[0] - 0.8, next[0])));
  }

